def build():
    files, sources, excerpts = {}, {}, []
    for key,(rel,start,end,title) in specs.items():
        data=(repo/rel).read_bytes()
        assert data==subprocess.check_output(['git','show',PIN+':'+rel],cwd=repo),rel
        lines=data.splitlines(keepends=True);end=end or len(lines)
        assert 1<=start<=end<=len(lines),(rel,start,end,len(lines))
        block=b''.join(lines[start-1:end])
        url=f'https://github.com/CocoSgt/riemann-hypothesis-lean/blob/{PIN}/{rel}'
        files[rel]={'path':rel,'sha256':sha(data),'bytes':len(data),'line_count':len(lines),'verified_equal_to_pinned_git_blob':True,'url':url}
        sources[key]={'id':PREFIX+'_SRC_'+key.upper(),'path':rel,'declaration':title,'line_start':start,'line_end':end,'source_commit':PIN,'full_file_sha256':sha(data),'file_sha256':sha(data),'range_sha256':sha(block),'range_bytes':len(block),'verified_equal_to_pinned_git_blob':True,'url':url+f'#L{start}-L{end}'}
        excerpts.append(f'[{sources[key]["id"]}] {title}\n{sources[key]["url"]}\n'+block.decode())
    text=(HERE/'main.tex').read_text();main_sha=sha(text.encode());lookup={}
    for m in re.finditer(r'% BEGIN (UCE\d+)\n.*?% END \1\n',text,re.S):
        lookup[m.group(1)]={'claim':m.group(1),'file':COMPONENT+'/main.tex','file_sha256':main_sha,'claim_sha256':sha(m.group().encode()),'line_start':text[:m.start()].count('\n')+1,'line_end':text[:m.end()].count('\n')}
    baseline=ROOT/'history/version_0_48/provenance.json'
    old={c['id']:c for c in json.loads(baseline.read_text())['claims']}
    inherited_ids={d for ds,_ in relations.values() for d in ds if isinstance(d,str)}
    boundary_ids={'HIA3'}
    for cid in inherited_ids|boundary_ids:
        loc=old[cid]['proof_location'];data=(ROOT/loc['file']).read_bytes()
        block=b''.join(data.splitlines(keepends=True)[loc['line_start']-1:loc['line_end']])
        assert sha(block)==loc['sha256'],cid
        lookup[cid]={'claim':cid,'file':loc['file'],'file_sha256':sha(data),'claim_sha256':sha(block),'line_start':loc['line_start'],'line_end':loc['line_end'],'kind':'immutable_inherited_human_proof' if cid in inherited_ids else 'explicit_boundary_not_a_premise','newly_modified_by_this_component':False}
    local={PREFIX+str(i) for i in relations}
    assert set(lookup)-inherited_ids-boundary_ids==local
    claims=[]
    for i,(deps,ss) in relations.items():
        cid=PREFIX+str(i);m=re.search(r'% BEGIN '+cid+r'\n.*?% END '+cid+r'\n',text,re.S);assert m,cid
        ds=[PREFIX+str(d) if isinstance(d,int) else d for d in deps]
        assert set(ds)<=local|inherited_ids,(cid,set(ds)-set(lookup))
        start=text[:m.start()].count('\n')+1
        claim={'id':cid,'title':re.search(r'\\paragraph\{'+cid+r'\. (.*?)\}\n',m.group(),re.S).group(1),'introduced_in':VERSION,'classification':'B','depends_on':ds,'external_input_ids':ext_uses[i],'published_input_ids':[],'proof_location':{'file':COMPONENT+'/main.tex','label':'claim:'+cid,'line_start':start,'line_end':start+m.group().count('\n')-1,'sha256':sha(m.group().encode()),'bytes':len(m.group().encode())},'sources':[sources[k] for k in ss],'source_proof_is_not_human_proof':True}
        if cid in nonpremise:claim['non_premise_reference_explanations']=nonpremise[cid]
        claims.append(claim)
    edges={c['id']:[d for d in c['depends_on'] if d in local] for c in claims};done=set();active=set()
    def visit(cid):
        assert cid not in active,('dependency cycle',cid)
        if cid in done:return
        active.add(cid)
        for d in edges[cid]:visit(d)
        active.remove(cid);done.add(cid)
    for cid in local:visit(cid)
    for e in external:
        e['source_bindings']=[sources[k] for k in e.get('source_keys',[])]
        e['registry_bindings']=[{'file':p,'sha256':sha((ROOT/p).read_bytes())} for p in e.get('registry_files',[])]
        e['boundary_proof_bindings']=[lookup[cid] for cid in e.get('boundary_human_endpoints',[])]
    ext_ids={e['id'] for e in external}
    assert all(set(c['external_input_ids'])<=ext_ids for c in claims)
    reviews=[]
    paths=list(HERE.glob('review_*.json'))
    root_review=ROOT/'reviews_v0_49'/f'{COMPONENT}_root_review.json'
    if root_review.exists():paths.append(root_review)
    for p in paths:
        v=json.loads(p.read_text());assert v.get('result',v.get('status'))=='PASS',p
        ids=[]
        for entry in v.get('claims_reviewed',v.get('reviewed_claims',[])):
            cid=entry if isinstance(entry,str) else entry.get('id',entry.get('claim'));assert cid in local,(p,cid)
            expected=v.get('proof_hashes',{}).get(cid) if isinstance(entry,str) else entry.get('proof_range_sha256',entry.get('block_sha256'))
            assert expected==lookup[cid]['claim_sha256'],(p,cid,'stale reviewed block');ids.append(cid)
        reviews.append({'file':str(p.relative_to(ROOT)),'sha256':sha(p.read_bytes()),'reviewer':v.get('reviewer'),'result':'PASS','reviewed_proof_file_sha256':v.get('proof_sha256',v.get('proof_file_sha256')),'proof_file_sha256':main_sha,'reviewed_blocks_unchanged':True,'claims':ids,'scope':v.get('scope')})
    reviewed={cid for r in reviews for cid in r['claims']}
    status='complete_at_stated_scope_independently_reviewed' if local<=reviewed else 'complete_at_stated_scope_pending_independent_review'
    for c in claims:
        c['status']='complete_at_stated_scope_independently_reviewed' if c['id'] in reviewed else 'complete_at_stated_scope_pending_independent_review'
        c['independent_review_files']=[r['file'] for r in reviews if c['id'] in r['claims']]
    contracts={'schema':'rh-human-component-contract/1','artifact_version':VERSION,'source_commit':PIN,'proof_file_sha256':main_sha,**config,'retained_foundations':[e['id'] for e in external],'original_admissibility_not_weakened':True,'selected_producer_closed':False}
    prov={'schema':'rh-human-component-provenance/1','component':COMPONENT,'artifact_version':VERSION,'source_commit':PIN,'proof_file_sha256':main_sha,'status':status,'claims':claims,'inherited_human_inputs':[lookup[cid] for cid in sorted(inherited_ids)],'boundary_human_references':[lookup[cid] for cid in sorted(boundary_ids)],'classical_and_foundational_inputs':external,'independent_reviews':reviews,'dependency_convention':'depends_on contains only numbered human claims. Retained ordinary-end premises and foundational inputs are named separately. UCE19 proves the original GdEnd implication; it does not supply the GdEnd premise or close AUT_UNRAM_COEF.','baseline_provenance':{'file':str(baseline.relative_to(ROOT)),'sha256':sha(baseline.read_bytes())},'source_proof_is_not_human_proof':True,'root_ledger_modified':False,'frozen_artifacts_modified':False}
    closure={'schema':'rh-human-component-closure/1','component':COMPONENT,'artifact_version':VERSION,'source_commit':PIN,'proof_file_sha256':main_sha,'status':status,'closed_subcontracts':config['subcontracts'],'proposed_global_frontier_leaf_closures':[],'new_global_frontier_leaf_closures':[],'foundation_retention_explicit':True,'independent_reviews':reviews,'validation':'Two-pass standalone draft TeX with exact proof hash, no Lean/kernel replay. Independent mathematical/source reviews bound by the listed numbered proof blocks.','pending':sorted(local-reviewed,key=lambda x:int(x[3:])),'AUT_UNRAM_COEF_remains_open':True,'GdEnd_remains_explicit_antecedent':True,'original_GD_unchanged':True}
    manifest={'schema':'rh-source-manifest/1','component':COMPONENT,'source_commit':PIN,'files':list(files.values()),'ranges':list(sources.values())}
